CSS = r'''
#import-drop{border:2px dashed var(--line2);border-radius:12px;padding:30px;text-align:center;cursor:pointer}
#import-drop.drag{border-color:var(--accent);background:var(--accentbg)}
#import-drop:focus-visible{outline:2px solid var(--accent)}
#import-list{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}
#import-list button[aria-pressed=true]{border-color:var(--accent);background:var(--accentbg)}
#import-select-bar{margin:16px 0 0}
#import-preview{overflow:auto;max-height:60vh}
.import-compare-pane{min-width:0}.import-compare-content{overflow:auto;max-height:48vh}
.import-changed{background:var(--warnbg);color:var(--text)}
'''
HTML = r'''
<div class="pagehead" data-view="files"><h2>文件处理</h2><p>导入文字或表格，整理结构并查看内容。</p></div>
<section data-view="files"><div id="import-drop" role="button" tabindex="0" aria-label="选择或拖入文件">拖文件到这里，或点击选择<br><small class="muted">TXT、Markdown、CSV、TSV、JSON、DOCX、XLSX、PDF · 每份最多512KB</small></div><input id="import-file" type="file" accept=".txt,.md,.csv,.tsv,.json,.docx,.xlsx,.pdf" hidden><p id="import-note" class="muted" role="status">原件保存在本机，不调用 AI。支持文字版 PDF；扫描图片暂不能识别。旧版 Word/Excel 请先另存为 DOCX/XLSX。</p><div id="import-select-bar" class="center-actions" hidden><button id="import-select-toggle">多选</button><button id="import-select-all" hidden>全选</button><button id="import-select-delete" hidden disabled>删除所选</button></div><div id="import-list"></div><h3 id="import-title">已导入文件</h3><div id="import-summary"></div><div id="import-preview"></div><p id="import-page" class="muted"></p><div class="center-actions"><button id="import-prev" hidden>上一页</button><button id="import-next" hidden>下一页</button><button id="import-delete" hidden>删除此文件</button></div></section>
<section data-view="files"><h2>对比导入文件</h2><div class="center-actions"><label>左侧文件<select id="import-compare-left"></select></label><label>右侧文件<select id="import-compare-right"></select></label><button id="import-compare-open">并排对比</button></div><p id="import-compare-note" class="muted" role="status">按行对比，黄色标出变化；左右可以分别翻页。</p></section>
'''
JS = r'''
let importedFiles=[],importId='',importOffset=0,importNext=null,importPageSize=16000;
let importComparison=null,importGeneration=0,importSelecting=false;const importSelected=new Set();
function importListRender(){for(const id of [...importSelected])if(!importedFiles.some(x=>x.id===id))importSelected.delete(id);if(!importedFiles.length)importSelecting=false;$('import-select-bar').hidden=!importedFiles.length;$('import-select-toggle').textContent=T(importSelecting?'取消多选':'多选');$('import-select-all').hidden=$('import-select-delete').hidden=!importSelecting;$('import-select-all').textContent=T(importSelected.size===importedFiles.length?'全不选':'全选');$('import-select-delete').disabled=!importSelected.size;$('import-select-delete').textContent=T('删除所选')+(importSelected.size?' ('+importSelected.size+')':'');reconcile($('import-list'),importedFiles.map(x=>'<button data-import-id="'+x.id+'"'+(importSelecting?' aria-pressed="'+importSelected.has(x.id)+'"':'')+'>'+(importSelecting&&importSelected.has(x.id)?'✓ ':'')+esc(x.name)+'</button>').join('')||'<p class="muted">'+T('尚未导入文件。')+'</p>');}
function importClearPreview(){importGeneration++;importId='';importNext=null;importOffset=0;$('import-title').textContent=T('已导入文件');$('import-summary').innerHTML='';$('import-preview').innerHTML='';$('import-page').textContent='';for(const x of ['import-prev','import-next','import-delete'])$(x).hidden=true;}
function importCompareChoices(){$('import-compare-open').disabled=importedFiles.length<2;for(const side of ['left','right']){const el=$('import-compare-'+side),value=el.value;reconcile(el,importedFiles.map(x=>'<option value="'+x.id+'">'+esc(x.name)+'</option>').join(''));if([...el.options].some(x=>x.value===value))el.value=value;}}
function importedContent(d){return d.unit==='rows'?'<table><tbody>'+d.content.map((row,i)=>'<tr><th scope="row" class="'+(d.changed_rows?.[i]?'import-changed':'')+'">'+(d.offset+i+1)+'</th>'+row.map((cell,j)=>'<td class="wrap '+(d.changed_columns?.[i]?.includes(j)?'import-changed':'')+'">'+esc(cell)+'</td>').join('')+'</tr>').join('')+'</tbody></table>':'<pre>'+esc(d.content)+'</pre>';}
async function compareImports(left,right,left_offset=0,right_offset=0){try{const d=await centerApi('imports/compare',{left,right,left_offset,right_offset});importComparison=d;openModal(T('导入文件对比'),'<p class="muted">'+T('对比文字与表格内容，不比较排版或图表。')+'</p><p>'+(d.equal?T('两份原件完全一致。'):d.content_equal?T('原件不同，整理后的内容一致。'):T('两份内容不同。'))+T('按')+(d.comparison_unit==='table_rows'?T('表格行'):T('文本行'))+T('位置比较：')+num(d.changed_positions)+T(' 处行内容不同')+(d.changed_cells===null?'':' · '+num(d.changed_cells)+T(' 处单元格不同'))+'。</p><div class="ovrow">'+['left','right'].map(side=>{const p=d[side];return '<div class="import-compare-pane"><h3>'+esc((side==='left'?T('左侧'):T('右侧'))+' · '+p.name)+'</h3>'+(p.summary.notes?.length?'<p class="muted">'+p.summary.notes.map(esc).join('<br>')+'</p>':'')+'<p class="muted">'+T(p.unit==='rows'?'行':'字符')+' '+T('位置 ')+p.offset+' / '+p.total+'</p><div class="import-compare-content">'+importedContent(p)+'</div><div class="center-actions">'+(p.offset>0?'<button data-import-page="prev" data-side="'+side+'">'+T('上一页')+'</button>':'')+(p.next_offset!==null?'<button data-import-page="next" data-side="'+side+'">'+T('下一页')+'</button>':'')+'</div></div>';}).join('')+'</div>');}catch(e){$('import-compare-note').textContent=e.message;}}
$('import-compare-open').disabled=true;
$('import-compare-open').onclick=()=>compareImports($('import-compare-left').value,$('import-compare-right').value);
$('modal-body').addEventListener('click',e=>{const b=e.target.closest('[data-import-page]');if(!b||!importComparison)return;const d=importComparison,p=d[b.dataset.side];const offset=b.dataset.importPage==='next'?p.next_offset:Math.max(0,p.offset-(p.unit==='rows'?25:16000));compareImports(d.left.id,d.right.id,b.dataset.side==='left'?offset:d.left.offset,b.dataset.side==='right'?offset:d.right.offset);});
async function loadImports(){try{importedFiles=(await centerApi('imports')).items;importCompareChoices();importListRender();}catch(e){$('import-note').textContent=e.message;}}
async function showImport(id,offset=0){const generation=++importGeneration;try{const d=await centerApi('imports/preview?id='+encodeURIComponent(id)+'&offset='+offset);if(generation!==importGeneration)return;importId=id;importOffset=d.offset;importNext=d.next_offset;importPageSize=d.unit==='rows'?25:16000;$('import-title').textContent=d.name;const s=d.summary;$('import-summary').innerHTML=d.unit==='rows'?('<p>'+num(s.rows)+T(' 行 · 最多 ')+num(s.columns)+T(' 列 · ')+num(s.ragged_rows)+T(' 行宽度不同 · ')+num(s.empty_cells)+T(' 个空单元格')+'</p>'):s.pages!==undefined?('<p>'+num(s.pages)+T(' 页 · ')+num(s.characters)+T(' 字符 · ')+num(s.empty_pages.length)+T(' 页没有可提取文字')+'</p>'):s.paragraphs!==undefined?('<p>'+num(s.paragraphs)+T(' 个正文段落 · ')+num(s.tables)+T(' 个表格 · ')+num(s.characters)+T(' 字符')+'</p>'):s.structure?('<p>JSON '+esc(s.structure)+' · '+num(s.items)+T(' 项')+'</p>'):('<p>'+num(s.characters)+T(' 字符 · ')+num(s.lines)+T(' 行 · ')+num(s.heading_count)+T(' 个标题')+'</p>'+(s.headings?.length?'<ul>'+s.headings.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>'+(s.more_headings?'<p class="muted">'+T('上方列出前20个标题；完整内容见下方分页。')+'</p>':''):''));if(s.notes?.length)$('import-summary').innerHTML+='<p>'+s.notes.map(esc).join('<br>')+'</p>'+(s.sheets?('<p>'+T('工作表：')+s.sheets.map(esc).join(', ')+' · '+num(s.cells)+T(' 个已存单元格 · ')+num(s.formulas)+T(' 个公式 · ')+num(s.missing_formula_results)+T(' 个公式缺少保存结果')+'</p>'):'');$('import-preview').innerHTML=importedContent(d);$('import-page').textContent=T('当前')+T(d.unit==='rows'?'行':'字符')+' '+T('位置 ')+d.offset+' / '+d.total+' · '+T('原件摘要 ')+d.sha256;$('import-prev').hidden=offset===0;$('import-delete').hidden=false;$('import-next').hidden=d.next_offset===null;}catch(e){$('import-note').textContent=e.message;}}
async function importFile(file){if(!file)return;if(file.size>512000){$('import-note').textContent=T('文件每份最多512KB。');return;}$('import-note').textContent=T('正在导入…');try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const item=await centerApi('imports/add',{name:file.name,data:btoa(binary)});$('import-note').textContent=T('已保存原件并整理结构。');await loadImports();await showImport(item.id);}catch(e){$('import-note').textContent=e.message;}finally{$('import-file').value='';}}
$('import-file').onchange=e=>importFile(e.target.files[0]);
$('import-drop').onclick=()=>$('import-file').click();
$('import-drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('import-file').click();}};
$('import-drop').ondragover=e=>{e.preventDefault();$('import-drop').classList.add('drag');};
$('import-drop').ondragleave=()=>$('import-drop').classList.remove('drag');
$('import-drop').ondrop=e=>{e.preventDefault();$('import-drop').classList.remove('drag');if(e.dataTransfer.files.length!==1){$('import-note').textContent=T('请一次导入一个文件。');return;}importFile(e.dataTransfer.files[0]);};
$('import-list').onclick=e=>{const b=e.target.closest('[data-import-id]');if(!b)return;if(!importSelecting)return showImport(b.dataset.importId);const id=b.dataset.importId;importSelected.has(id)?importSelected.delete(id):importSelected.add(id);importListRender();};
$('import-select-toggle').onclick=()=>{importSelecting=!importSelecting;importSelected.clear();importListRender();};
$('import-select-all').onclick=()=>{const all=importSelected.size===importedFiles.length;importSelected.clear();if(!all)for(const x of importedFiles)importSelected.add(x.id);importListRender();};
$('import-next').onclick=()=>showImport(importId,importNext);
$('import-prev').onclick=()=>showImport(importId,Math.max(0,importOffset-importPageSize));
// 原生壳不支持浏览器自带的 confirm()，用页面内对话框确认删除。
function importConfirmDelete(items){if(!items.length)return;openModal(T('删除导入文件'),'<p>'+T('将从本机导入库删除以下文件的保存副本和记录，删除后无法恢复：')+'</p><ul>'+items.map(x=>'<li>'+esc(x.name)+'</li>').join('')+'</ul><p class="muted">'+T('你电脑上的原始文件不受影响。')+'</p><div class="center-actions"><button data-import-delete="">'+T('取消')+'</button><button data-import-delete="'+items.map(x=>x.id).join(',')+'">'+T('确认删除')+(items.length>1?' ('+items.length+')':'')+'</button></div>');}
$('import-delete').onclick=()=>importConfirmDelete(importedFiles.filter(x=>x.id===importId));
$('import-select-delete').onclick=()=>importConfirmDelete(importedFiles.filter(x=>importSelected.has(x.id)));
$('modal-body').addEventListener('click',async e=>{const b=e.target.closest('[data-import-delete]');if(!b)return;const ids=b.dataset.importDelete.split(',').filter(Boolean);closeModal();if(!ids.length)return;try{const d=await centerApi('imports/delete',{ids});if(ids.includes(importId))importClearPreview();importSelecting=false;importSelected.clear();$('import-note').textContent=T('已删除导入文件：')+d.removed.length+T(' 份。');}catch(e){$('import-note').textContent=e.message;}await loadImports();});
loadImports();
'''
